import { AppProvider } from "./context/AppContext";
import EarthViewer from "./components/EarthViewer";
// ...other imports

export default function App() {
  return (
    <AppProvider>
      <div
        style={{
          width: "100vw",
          height: "100vh",
          background: "#000011",
          position: "relative",
        }}
      >
        <EarthViewer />
        <div
          style={{
            position: "absolute",
            top: 20,
            left: 20,
            color: "white",
            background: "rgba(0,0,0,0.5)",
            padding: "8px",
            borderRadius: "8px",
            zIndex: 10,
          }}
        >
          Overlay Test
        </div>
      </div>
    </AppProvider>
  );
}
